def solve(inputs: dict) -> float:
    # Find keys for residues and moduli
    residues = None
    moduli = None
    for k, v in inputs.items():
        if isinstance(v, list):
            kl = k.lower()
            if 'mod' in kl or 'modul' in kl:
                moduli = v
            elif 'res' in kl or 'rem' in kl or 'x' in kl:
                residues = v
    # fallback: assume two lists
    if residues is None or moduli is None:
        lists = [v for v in inputs.values() if isinstance(v, list)]
        if len(lists) == 2:
            residues, moduli = lists[0], lists[1]
    residues = [int(r) for r in residues]
    moduli = [int(m) for m in moduli]
    M = 1
    for m in moduli:
        M *= m
    x = 0
    for r, m in zip(residues, moduli):
        Mi = M // m
        inv = pow(Mi, -1, m)
        x += r * Mi * inv
    return float(x % M)

